def retry_request(operation, sleep, max_attempts=3, idempotency_key="request-1"):
    if type(max_attempts) is not int or not 1 <= max_attempts <= 5:
        raise ValueError("Invalid attempt budget")
    if not isinstance(idempotency_key, str) or not idempotency_key:
        raise ValueError("Invalid key")
    for index in range(max_attempts):
        try:
            response = operation(idempotency_key)
        except TimeoutError:
            response = {"status": 504, "body": {"error": "timeout"}}
        if response["status"] not in {429, 503, 504} or index == max_attempts - 1:
            return {"attempts": index + 1, "response": response}
        sleep(0.1 * 2 ** index)

