def summarize_slots(bookings):
    if not isinstance(bookings, list):
        raise ValueError("Expected a list")
    totals = {}
    for row in bookings:
        if not isinstance(row, dict) or set(row) != {"room", "start", "end"}:
            raise ValueError("Invalid booking")
        if not isinstance(row["room"], str) or not row["room"].strip():
            raise ValueError("Invalid room")
        if type(row["start"]) is not int or type(row["end"]) is not int or row["start"] < 0 or row["end"] <= row["start"]:
            raise ValueError("Invalid times")
        record = totals.setdefault(row["room"], {"room": row["room"], "minutes": 0, "bookings": 0})
        record["minutes"] += row["end"] - row["start"]
        record["bookings"] += 1
    return sorted(totals.values(), key=lambda row: (-row["minutes"], row["room"]))

