import math

def rank_readings(readings, limit=3):
    if not isinstance(readings, list) or type(limit) is not int or limit < 0:
        raise ValueError("Invalid arguments")
    groups = {}
    for row in readings:
        if not isinstance(row, dict) or set(row) != {"sensor", "value"}:
            raise ValueError("Invalid reading")
        if not isinstance(row["sensor"], str) or not row["sensor"].strip() or type(row["value"]) not in (int, float) or not math.isfinite(row["value"]):
            raise ValueError("Invalid values")
        groups.setdefault(row["sensor"], []).append(row["value"])
    result = [{"sensor": sensor, "mean": sum(values) / len(values), "samples": len(values)} for sensor, values in groups.items()]
    return sorted(result, key=lambda row: (-row["mean"], row["sensor"]))[:limit]

