from copy import deepcopy

def dispatch_jobs(jobs, execute):
    if not isinstance(jobs, list):
        raise ValueError("Expected jobs")
    for job in jobs:
        if not isinstance(job, dict) or set(job) != {"job_id", "payload"} or not isinstance(job["job_id"], str) or not job["job_id"].strip() or not isinstance(job["payload"], dict):
            raise ValueError("Invalid job")
    results = []
    cache = {}
    for job in jobs:
        key = job["job_id"]
        if key in cache:
            payload, result = cache[key]
            if payload != job["payload"]:
                result = {"job_id": key, "ok": False, "error": "conflict"}
            results.append(deepcopy(result))
            continue
        payload = deepcopy(job["payload"])
        try:
            result = {"job_id": job["job_id"], "ok": True, "value": execute(job["payload"])}
        except Exception as error:
            result = {"job_id": job["job_id"], "ok": False, "error": type(error).__name__}
        cache[key] = (payload, deepcopy(result))
        results.append(result)
    return results

